                field_storage.FHE_SLOT[i0].BASE_H.ADDR.value <= field_combo.FHE_SLOT[i0].BASE_H.ADDR.next;
            end
        end
        assign hwif_out.FHE_SLOT[i0].BASE_H.ADDR.value = field_storage.FHE_SLOT[i0].BASE_H.ADDR.value;
    end

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    always_comb begin
        automatic logic wr_ack;
        wr_ack = '0;
        wr_ack |= hwif_in.FHE_CTRL.wr_ack;
        external_wr_ack = wr_ack;
    end
    assign cpuif_wr_ack = external_wr_ack | (decoded_req & decoded_req_is_wr & ~decoded_strb_is_external);
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------
    logic readback_external_rd_ack_c;
    always_comb begin
        automatic logic rd_ack;
        rd_ack = '0;
        
        readback_external_rd_ack_c = rd_ack;
    end

    logic readback_external_rd_ack;

    assign readback_external_rd_ack = readback_external_rd_ack_c;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;

    // Assign readback values to a flattened array
    logic [19-1:0][31:0] readback_array;
    for(genvar i0=0; i0<2; i0++) begin
        assign readback_array[i0*1 + 0][31:0] = (decoded_reg_strb.FHE_NAME[i0] && !decoded_req_is_wr) ? hwif_in.FHE_NAME[i0].NAME.next : '0;
    end
    for(genvar i0=0; i0<2; i0++) begin
        assign readback_array[i0*1 + 2][31:0] = (decoded_reg_strb.FHE_VERSION[i0] && !decoded_req_is_wr) ? hwif_in.FHE_VERSION[i0].VERSION.next : '0;
    end
    assign readback_array[4][0:0] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.READY.next : '0;
    assign readback_array[4][1:1] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.VALID.next : '0;
    assign readback_array[4][2:2] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.ERROR.next : '0;
    assign readback_array[4][3:3] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.KEY_VALID.next : '0;
    assign readback_array[4][7:4] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.ERR_CAUSE.next : '0;
    assign readback_array[4][8:8] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.COMMIT_WAIT.next : '0;
    assign readback_array[4][9:9] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.DMA_LEASED.next : '0;
    assign readback_array[4][31:10] = (decoded_reg_strb.FHE_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_STATUS.RSVD.next : '0;
    assign readback_array[5][3:0] = (decoded_reg_strb.FHE_CONFIG && !decoded_req_is_wr) ? field_storage.FHE_CONFIG.L.value : '0;
    assign readback_array[5][7:4] = (decoded_reg_strb.FHE_CONFIG && !decoded_req_is_wr) ? field_storage.FHE_CONFIG.LOGN.value : '0;
    assign readback_array[5][15:8] = (decoded_reg_strb.FHE_CONFIG && !decoded_req_is_wr) ? 8'h0 : '0;
    assign readback_array[5][27:16] = (decoded_reg_strb.FHE_CONFIG && !decoded_req_is_wr) ? field_storage.FHE_CONFIG.SCALE.value : '0;
    assign readback_array[5][31:28] = (decoded_reg_strb.FHE_CONFIG && !decoded_req_is_wr) ? 4'h0 : '0;
    assign readback_array[6][15:0] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.N.next : '0;
    assign readback_array[6][19:16] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.L.next : '0;
    assign readback_array[6][20:20] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.FFT_GENERATED.next : '0;
    assign readback_array[6][23:21] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.RSVD0.next : '0;
    assign readback_array[6][24:24] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.DMA_STREAM.next : '0;
    assign readback_array[6][27:25] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.RSVD1.next : '0;
    assign readback_array[6][31:28] = (decoded_reg_strb.FHE_CAP && !decoded_req_is_wr) ? hwif_in.FHE_CAP.MAP_VERSION.next : '0;
    assign readback_array[7][0:0] = (decoded_reg_strb.FHE_KV_RD_SEED_CTRL && !decoded_req_is_wr) ? field_storage.FHE_KV_RD_SEED_CTRL.read_en.value : '0;
    assign readback_array[7][5:1] = (decoded_reg_strb.FHE_KV_RD_SEED_CTRL && !decoded_req_is_wr) ? field_storage.FHE_KV_RD_SEED_CTRL.read_entry.value : '0;
    assign readback_array[7][6:6] = (decoded_reg_strb.FHE_KV_RD_SEED_CTRL && !decoded_req_is_wr) ? field_storage.FHE_KV_RD_SEED_CTRL.pcr_hash_extend.value : '0;
    assign readback_array[7][31:7] = (decoded_reg_strb.FHE_KV_RD_SEED_CTRL && !decoded_req_is_wr) ? field_storage.FHE_KV_RD_SEED_CTRL.rsvd.value : '0;
    assign readback_array[8][0:0] = (decoded_reg_strb.FHE_KV_RD_SEED_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_KV_RD_SEED_STATUS.READY.next : '0;
    assign readback_array[8][1:1] = (decoded_reg_strb.FHE_KV_RD_SEED_STATUS && !decoded_req_is_wr) ? field_storage.FHE_KV_RD_SEED_STATUS.VALID.value : '0;
    assign readback_array[8][9:2] = (decoded_reg_strb.FHE_KV_RD_SEED_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_KV_RD_SEED_STATUS.ERROR.next : '0;
    assign readback_array[8][31:10] = '0;
    assign readback_array[9][0:0] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.ACTIVE.next : '0;
    assign readback_array[9][1:1] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.DIR.next : '0;
    assign readback_array[9][3:2] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.RSVD0.next : '0;
    assign readback_array[9][6:4] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.SLOT.next : '0;
    assign readback_array[9][7:7] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.RSVD1.next : '0;
    assign readback_array[9][11:8] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.LIMB.next : '0;
    assign readback_array[9][31:12] = (decoded_reg_strb.FHE_XFER_STATUS && !decoded_req_is_wr) ? hwif_in.FHE_XFER_STATUS.RSVD2.next : '0;
    assign readback_array[10][31:0] = (decoded_reg_strb.FHE_XFER_LEFT && !decoded_req_is_wr) ? hwif_in.FHE_XFER_LEFT.LEFT.next : '0;
    for(genvar i0=0; i0<4; i0++) begin
        assign readback_array[i0*2 + 11][31:0] = (decoded_reg_strb.FHE_SLOT[i0].BASE_L && !decoded_req_is_wr) ? field_storage.FHE_SLOT[i0].BASE_L.ADDR.value : '0;
        assign readback_array[i0*2 + 12][31:0] = (decoded_reg_strb.FHE_SLOT[i0].BASE_H && !decoded_req_is_wr) ? field_storage.FHE_SLOT[i0].BASE_H.ADDR.value : '0;
    end

    // Reduce the array
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_strb_is_external;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<19; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;

`CALIPTRA_ASSERT_KNOWN(ERR_HWIF_IN, hwif_in, clk, !hwif_in.reset_b)

endmodule
